WITH base AS (SELECT * FROM stores WHERE sqft = 7452), summary AS (SELECT QUARTER(opened_date) AS opened_quarter, region, ROUND(AVG(sqft), 2) AS avg_sqft, SUM(CASE WHEN region = 'South' THEN sqft ELSE 0 END) AS south_sqft FROM base GROUP BY QUARTER(opened_date), region) SELECT opened_quarter, region, avg_sqft, south_sqft FROM summary ORDER BY avg_sqft DESC, opened_quarter, region LIMIT 3
